revision.text:
.infobox {
  width            : 30em              ;
  font-size        : 90%               ; 
  border           : 1px solid #aaaaaa ;
  background-color : #f9f9f9           ;
  color            : black             ;
  margin-bottom    : 0.5em             ;
  margin-left      : 1em               ;
  padding          : 0.2em             ;
  float            : right             ;
  clear            : right             ;
  text-align       : left              ; }

.infoboxHeader {
  text-align       : center  ;
  background-color : #ccccff ; }

.infobox td      { background-color : #efefff   }
.infobox th      { background-color : #e0e0ff   }

.infobox caption {
   background-color : #ccccff ;
   font-weight      : bold    ; }

{| style="width: 30em; font-size: 90%; border: 1px solid #aaaaaa; background-color: #f9f9f9; color: black; margin-bottom: 0.5em; margin-left: 1em; padding: 0.2em; float: right; clear: right; text-align:left;"
! style="text-align: center; background-color:#ccccff;" colspan="2" |<big>[[Special:Categories|Category]] data</big> {{
